<title>DUSTLINE — Sector 7 · tactical FPS</title>
<style>
  /* Look plan: dark slate canvas, warm amber accent, one danger red. */
  :root {
    --canvas: #14161a;
    --surface: #1e2228;
    --hairline: #2c323a;
    --ink: #e9e6df;
    --muted: #98a0a8;
    --accent: #f0a830;
    --danger: #ff5a2a;
    --good: #2fa36b;
    --ally: #3aa7e1;
    --font-ui: system-ui, -apple-system, 'Segoe UI', sans-serif;
    --font-readout: ui-monospace, 'SF Mono', Menlo, monospace;
  }
  * { box-sizing: border-box; }
  html, body { margin: 0; height: 100%; overflow: hidden; background: var(--canvas); color: var(--ink); font-family: var(--font-ui); }
  #game, #game canvas { position: fixed; inset: 0; display: block; }
  #hud { position: fixed; inset: 0; pointer-events: none; }

  #crosshair { position: fixed; left: 50%; top: 50%; width: 22px; height: 22px; transform: translate(-50%, -50%); --gap: 5px; }
  #crosshair.hidden { display: none; }
  #crosshair i { position: absolute; background: var(--ink); opacity: .9; }
  #crosshair i:nth-child(1) { left: 10px; top: calc(11px - var(--gap) - 7px); width: 2px; height: 7px; }
  #crosshair i:nth-child(2) { left: 10px; top: calc(11px + var(--gap)); width: 2px; height: 7px; }
  #crosshair i:nth-child(3) { top: 10px; left: calc(11px - var(--gap) - 7px); height: 2px; width: 7px; }
  #crosshair i:nth-child(4) { top: 10px; left: calc(11px + var(--gap)); height: 2px; width: 7px; }
  #crosshair b { position: absolute; left: 10px; top: 10px; width: 2px; height: 2px; background: var(--ink); }

  #hitmarker { position: fixed; left: 50%; top: 50%; width: 26px; height: 26px; transform: translate(-50%, -50%) rotate(45deg); opacity: 0; }
  #hitmarker.on { opacity: 1; }
  #hitmarker.kill i { background: var(--danger); }
  #hitmarker i { position: absolute; background: var(--accent); }
  #hitmarker i:nth-child(1) { left: 12px; top: 0; width: 2px; height: 8px; }
  #hitmarker i:nth-child(2) { left: 12px; bottom: 0; width: 2px; height: 8px; }
  #hitmarker i:nth-child(3) { top: 12px; left: 0; height: 2px; width: 8px; }
  #hitmarker i:nth-child(4) { top: 12px; right: 0; height: 2px; width: 8px; }

  #hurt { position: fixed; inset: 0; pointer-events: none; opacity: 0; box-shadow: inset 0 0 90px 30px rgba(255, 60, 30, .55); transition: opacity 120ms linear; }
  #hurt.on { opacity: 1; }

  .panel-bl { position: fixed; left: 28px; bottom: 22px; font-family: var(--font-readout); }
  #hp-row { display: flex; align-items: baseline; gap: 10px; }
  #hp-value { font-size: 44px; line-height: 1; }
  #hp-label { font-size: 12px; color: var(--muted); letter-spacing: .12em; }
  #hp-track { width: 180px; height: 6px; background: var(--hairline); margin-top: 6px; }
  .hp-fill { height: 100%; background: var(--good); width: 100%; }
  .hp-fill.low { background: var(--danger); }
  #spike { margin-top: 10px; font-size: 13px; color: var(--accent); }

  #ammo { position: fixed; right: 32px; bottom: 22px; text-align: right; font-family: var(--font-readout); }
  #ammo-row { display: flex; align-items: baseline; gap: 8px; justify-content: flex-end; }
  #ammo-mag { font-size: 56px; line-height: 1; }
  #ammo-reserve { font-size: 16px; color: var(--muted); }
  #ammo.empty #ammo-mag { color: var(--danger); }
  #ammo.reloading #ammo-mag { color: var(--accent); }
  #weapon-name { font-size: 13px; color: var(--muted); margin-top: 4px; }

  #topbar { position: fixed; top: 18px; left: 50%; transform: translateX(-50%); text-align: center; font-family: var(--font-readout); }
  #timer-value { font-size: 30px; }
  #timer-value.urgent { color: var(--danger); }
  #timer-label { font-size: 11px; letter-spacing: .18em; color: var(--muted); }
  #score-line { margin-top: 2px; font-size: 13px; color: var(--muted); }
  #score-line b { color: var(--ink); }

  #money { position: fixed; top: 20px; right: 28px; font-family: var(--font-readout); text-align: right; }
  #money-value { font-size: 22px; color: var(--accent); }
  #money-label { font-size: 11px; letter-spacing: .14em; color: var(--muted); }
  #bots-value { margin-top: 4px; font-size: 12px; color: var(--muted); }

  #killfeed { position: fixed; top: 20px; left: 28px; font-family: var(--font-readout); font-size: 13px; color: var(--muted); display: grid; gap: 4px; }
  #killfeed div:first-child { color: var(--ink); }

  #minimap { position: fixed; right: 28px; top: 96px; border: 1px solid var(--hairline); background: rgba(20,22,26,.8); }

  #banner { position: fixed; left: 50%; top: 30%; transform: translate(-50%, -50%); text-align: center; opacity: 0; transition: opacity 200ms; }
  #banner.show { opacity: 1; }
  #banner-text { font-size: 52px; font-weight: 600; letter-spacing: .04em; }
  #banner-sub { font-size: 16px; color: var(--muted); margin-top: 6px; }
  #banner.win #banner-text { color: var(--good); }
  #banner.lose #banner-text { color: var(--danger); }

  #plant { position: fixed; left: 50%; bottom: 22%; transform: translateX(-50%); width: 260px; text-align: center; }
  #plant-label { font-size: 12px; letter-spacing: .14em; color: var(--accent); margin-bottom: 6px; }
  #plant-track { height: 6px; background: var(--hairline); }
  #plant-fill { height: 100%; background: var(--accent); width: 0; }

  .overlay { position: fixed; inset: 0; display: grid; place-items: center; padding: 24px; background: rgba(20,22,26,.88); z-index: 10; }
  .overlay[hidden] { display: none; }
  .panel { width: min(520px, 100%); padding: 32px; background: var(--surface); border: 1px solid var(--hairline); }
  .panel h1 { margin: 0 0 8px; font-size: 32px; line-height: 1.15; font-weight: 600; letter-spacing: -0.02em; }
  .panel h1 .amber { color: var(--accent); }
  .panel p { margin: 0 0 24px; font-size: 15px; line-height: 1.55; color: var(--muted); }
  #play { font: inherit; font-weight: 600; padding: 12px 20px; border: 1px solid var(--accent); background: var(--accent); color: var(--canvas); cursor: pointer; }
  #play:hover { background: var(--ink); border-color: var(--ink); }
  .keys { margin: 24px 0 0; padding: 0; list-style: none; display: grid; grid-template-columns: 1fr 1fr; gap: 8px; font-size: 13px; color: var(--muted); }
  .keys li { display: flex; align-items: center; gap: 6px; }
  .keys kbd { min-width: 24px; padding: 2px 6px; border: 1px solid var(--hairline); font-family: var(--font-readout); font-size: 12px; color: var(--ink); text-align: center; }

  #buy { position: fixed; inset: 0; display: grid; place-items: center; background: rgba(20,22,26,.72); z-index: 9; pointer-events: auto; }
  #buy[hidden] { display: none; }
  #buy .panel { width: min(560px, 100%); }
  #buy-grid { display: grid; gap: 8px; }
  .buy-item { display: grid; grid-template-columns: 28px 1fr auto; gap: 4px 10px; align-items: center; text-align: left; font: inherit; padding: 10px 12px; background: var(--canvas); border: 1px solid var(--hairline); color: var(--ink); cursor: pointer; }
  .buy-item:hover { border-color: var(--accent); }
  .buy-item.owned { border-color: var(--good); opacity: .75; }
  .buy-item.poor { opacity: .45; }
  .buy-key { font-family: var(--font-readout); color: var(--accent); text-align: center; border: 1px solid var(--hairline); padding: 2px 0; }
  .buy-name { font-weight: 600; }
  .buy-desc { grid-column: 2; font-size: 12px; color: var(--muted); }
  .buy-price { grid-row: 1 / 3; grid-column: 3; font-family: var(--font-readout); color: var(--accent); }
  #buy-money { font-family: var(--font-readout); color: var(--accent); font-size: 20px; }
  #buy-hint { font-size: 12px; color: var(--muted); margin-top: 12px; }
</style>
</head>
